// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/links", wrapper.CreateLink)
	router.POST(options.BaseURL+"/links/batch", wrapper.CreateLinks)
	router.GET(options.BaseURL+"/links/lookup", wrapper.LookupLink)
	router.GET(options.BaseURL+"/links/:slug", wrapper.GetLink)
	router.GET(options.BaseURL+"/links/:slug/resolve", wrapper.ResolveLink)
	router.POST(options.BaseURL+"/links/:slug/policy/refresh", wrapper.RefreshLinkPolicy)
	router.GET(options.BaseURL+"/links/:slug/asset", wrapper.RenderLinkAsset)
	router.GET(options.BaseURL+"/links/:slug/stats", wrapper.GetLinkStats)
	router.GET(options.BaseURL+"/repositories", wrapper.ListRepositories)
	router.GET(options.BaseURL+"/repositories/top", wrapper.ListTopRepositories)
	router.GET(options.BaseURL+"/coverage", wrapper.GetCoverage)
	router.GET(options.BaseURL+"/repositories/:slug", wrapper.GetRepository)
	router.GET(options.BaseURL+"/languages", wrapper.ListLanguages)
	router.POST(options.BaseURL+"/contact/reveal", wrapper.RevealContact)
	router.GET(options.BaseURL+"/automation/usage", wrapper.GetAutomationUsage)
}

